    CHECK_EQ(hir->routes[0].locals[1].init.int_value, 9223372036854775807LL);
    CHECK_EQ(hir->routes[0].locals[2].init.int_value, static_cast<i64>(0x8000000000000000ull));
    CHECK_EQ(hir->routes[0].locals[3].init.int_value, 0);

