TEST(frontend, analyze_nested_respond_calls_order_argument_guard_first) {
    const char* src =
        "func inner(ok: bool) -> i32 { guard ok else { respond 401 } 1 }\n"
        "func outer(ok: bool, value: i32) -> i32 { guard ok else { respond 402 } value }\n"
        "route GET \"/x\" { let code = outer(false, inner(false)) return 200 }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(ast);
    auto hir = analyze_file_heap(ast.value());
    REQUIRE(hir);
    REQUIRE_EQ(hir->routes.len, 1u);
    const auto& route = hir->routes[0];
    REQUIRE_EQ(route.guards.len, 2u);
    CHECK_EQ(route.guards[0].fail_term.status_code, 401);
    CHECK_EQ(route.guards[1].fail_term.status_code, 402);
    CHECK(route.guards[0].span.start <= route.guards[1].span.start);
}

TEST(frontend, parse_return_response_with_body) {
    // Covers the body: "..." kwarg through the compile-side pipeline:
    // parser → AST.response_body, analyze → HirTerminator.response_body,
    // lower_rir → rir::Module::response_bodies (non-empty entry interned,
    // body_idx = 1). Codegen and runtime behavior are exercised by
    // tests/test_integration.cc::dsl_response_body_real_socket.
    const char* src = "route GET \"/x\" { return response(200, body: \"Hello\") }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(ast);
    REQUIRE_EQ(ast->items.len, 1u);
    REQUIRE_EQ(ast->items[0].route.statements.len, 1u);
    const AstStatement& stmt = *ast->items[0].route.statements[0];
    CHECK_EQ(stmt.status_code, 200u);
    REQUIRE_EQ(stmt.response_body.len, 5u);
    CHECK(stmt.response_body.eq(lit("Hello")));
    CHECK(stmt.has_response_body);
    auto hir = analyze_file_heap(ast.value());
    REQUIRE(hir);
    REQUIRE_EQ(hir->routes.len, 1u);
    const auto& term = hir->routes[0].control.direct_term;
    CHECK_EQ(static_cast<u8>(term.kind), static_cast<u8>(HirTerminatorKind::ReturnStatus));
    CHECK_EQ(term.status_code, 200);
    REQUIRE_EQ(term.response_body.len, 5u);
    CHECK(term.response_body.eq(lit("Hello")));
    // Lower through MIR → RIR and verify a single body was interned at
    // slot 0 (body_idx 1) with the exact bytes.
    auto mir = build_mir_heap(hir.value());
    REQUIRE(mir);
    FrontendRirModule rir{};
    auto lowered = lower_to_rir(mir.value(), rir);
    REQUIRE(lowered);
    REQUIRE_EQ(rir.module.response_body_count, 1u);
    REQUIRE_EQ(rir.module.response_bodies[0].len, 5u);
    CHECK(rir.module.response_bodies[0].eq(lit("Hello")));
    rir.destroy();
}

TEST(frontend, parse_return_response_empty_body_is_noop) {
    // `body: ""` has the explicit-empty flag but zero bytes; HIR
    // preserves the kwarg (ptr != nullptr, len == 0 — the documented
    // sentinel), and lower_rir treats it as "no custom body" so no
    // entry is interned into the module table.
    const char* src = "route GET \"/x\" { return response(200, body: \"\") }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(ast);
    REQUIRE_EQ(ast->items.len, 1u);
    REQUIRE_EQ(ast->items[0].route.statements.len, 1u);
    CHECK(ast->items[0].route.statements[0]->has_response_body);
    auto hir = analyze_file_heap(ast.value());
    REQUIRE(hir);
    // HIR preserves the explicit kwarg via ptr-based sentinel: ptr
    // non-null distinguishes `body: ""` from the no-kwarg case even
    // though len == 0 in both. Asserting ptr != nullptr catches
    // regressions that would silently drop the kwarg.
    const auto& term = hir->routes[0].control.direct_term;
    CHECK(term.response_body.ptr != nullptr);
    CHECK_EQ(term.response_body.len, 0u);
    // Lower through MIR → RIR and verify the module table stays empty:
    // zero-length bodies should not produce an intern entry.
    auto mir = build_mir_heap(hir.value());
    REQUIRE(mir);
    FrontendRirModule rir{};
    auto lowered = lower_to_rir(mir.value(), rir);
    REQUIRE(lowered);
    CHECK_EQ(rir.module.response_body_count, 0u);
    rir.destroy();
}

TEST(frontend, parse_return_response_rejects_unknown_kwarg) {
    const char* src = "route GET \"/x\" { return response(200, header: \"foo\") }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(!ast);
    CHECK_EQ(ast.error().code, FrontendError::UnexpectedToken);
    CHECK(ast.error().detail.eq(lit("header")));
}

TEST(frontend, parse_return_forward_name) {
    // `return forward(<ident>)` is the only accepted spelling —
    // analyze resolves the ident to an upstream_index, HIR stores it
    // on the ForwardUpstream terminator, and RIR lowers to RetForward
    // with that index as the operand. Runtime dispatch is covered by
    // integration tests; here we just verify the compile-side path.
    const char* src = "upstream api\nroute GET \"/users\" { return forward(api) }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(ast);
    REQUIRE_EQ(ast->items.len, 2u);
    // Route has a single ForwardUpstream statement naming "api".
    const auto& route = ast->items[1].route;
    REQUIRE_EQ(route.statements.len, 1u);
    const AstStatement& stmt = *route.statements[0];
    CHECK_EQ(static_cast<u8>(stmt.kind), static_cast<u8>(AstStmtKind::ForwardUpstream));
    CHECK(stmt.name.eq(lit("api")));
    // HIR resolves the name to upstream_index 0.
    auto hir = analyze_file_heap(ast.value());
    REQUIRE(hir);
    REQUIRE_EQ(hir->upstreams.len, 1u);
    const auto& term = hir->routes[0].control.direct_term;
    CHECK_EQ(static_cast<u8>(term.kind), static_cast<u8>(HirTerminatorKind::ForwardUpstream));
    CHECK_EQ(term.upstream_index, 0u);
}

