TEST(frontend, parse_guard_req_method_eq_post) {
    // `guard req.method == POST else { return 405 }` — the keystone
    // use case. Parser yields LitMethod + Field(Ident("req"), "method");
    // analyze routes the Field through the magic `req.X` path when
    // `req` isn't shadowed by a local/variant/import, producing
    // typed HIR ReqMethod / ConstMethod. MIR/RIR downstream carry
    // those opcodes; codegen emits an i8 constant and a helper call
    // that reads the parsed method from the request.
    const char* src =
        "route GET \"/\" { guard req.method == POST else { return 405 } return 200 }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(ast);
    auto hir = analyze_file_heap(ast.value());
    REQUIRE(hir);
    REQUIRE_EQ(hir->routes.len, 1u);
    // Lower fully through MIR → RIR so we know codegen gets the right
    // inputs. The parser / analyzer paths are the ones that changed;
    // downstream is reused machinery.
    auto mir = build_mir_heap(hir.value());
    REQUIRE(mir);
    FrontendRirModule rir{};
    auto lowered = lower_to_rir(mir.value(), rir);
    REQUIRE(lowered);
    rir.destroy();
}

TEST(frontend, parse_req_path_regex_match_lowers_to_rir) {
    const char* src =
        "route GET \"/\" { guard req.path.matches(re\"^/v[0-9]+/users$\") else { return 404 } "
        "return 200 }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(ast);
    auto hir = analyze_file_heap(ast.value());
    REQUIRE(hir);
    REQUIRE_EQ(hir->routes.len, 1u);
    REQUIRE_EQ(hir->routes[0].guards.len, 1u);
    const auto& cond = hir->routes[0].guards[0].cond;
    CHECK_EQ(static_cast<u8>(cond.kind), static_cast<u8>(HirExprKind::RegexMatch));
    REQUIRE(cond.lhs != nullptr);
    CHECK_EQ(static_cast<u8>(cond.lhs->kind), static_cast<u8>(HirExprKind::ReqPath));
    CHECK(cond.str_value.eq(lit("^/v[0-9]+/users$")));

    auto mir = build_mir_heap(hir.value());
    REQUIRE(mir);
    FrontendRirModule rir{};
    auto lowered = lower_to_rir(mir.value(), rir);
    REQUIRE(lowered);
    REQUIRE_EQ(rir.module.func_count, 1u);
    CHECK(block_has_op(rir.module.functions[0].blocks[0], rir::Opcode::ReqPath));
    CHECK(block_has_op(rir.module.functions[0].blocks[0], rir::Opcode::StrRegexMatch));
    rir.destroy();
}

TEST(frontend, req_path_regex_match_alias_lowers_to_str_regex) {
    const char* src =
        "route GET \"/\" { let p = req.path guard p.matches(re\"^/v[0-9]+/users$\") else { "
        "return 404 } return 200 }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(ast);
    auto hir = analyze_file_heap(ast.value());
    REQUIRE(hir);
    REQUIRE_EQ(hir->routes.len, 1u);
    REQUIRE_EQ(hir->routes[0].guards.len, 1u);
    const auto& cond = hir->routes[0].guards[0].cond;
    CHECK_EQ(static_cast<u8>(cond.kind), static_cast<u8>(HirExprKind::RegexMatch));

    auto mir = build_mir_heap(hir.value());
    REQUIRE(mir);
    FrontendRirModule rir{};
    auto lowered = lower_to_rir(mir.value(), rir);
    REQUIRE(lowered);
    REQUIRE_EQ(rir.module.func_count, 1u);
    const auto& block = rir.module.functions[0].blocks[0];
    CHECK_EQ(block_op_count(block, rir::Opcode::StrRegexMatch), 1u);
    rir.destroy();
}

