TEST(frontend, parse_return_response_with_headers) {
    // Headers dict carries through parser → HIR → MIR → RIR:
    // intern_response_headers writes one set into rir::Module's flat
    // pool and the emit_ret_status imm packs headers_idx=1 alongside
    // body_idx. Codegen and runtime behaviour are covered by
    // tests/test_integration.cc::dsl_response_headers_real_socket.
    const char* src =
        "route GET \"/x\" { return response(200, headers: "
        "{ \"X-Service\": \"auth\", \"Cache-Control\": \"no-store\" }) }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(ast);
    REQUIRE_EQ(ast->items.len, 1u);
    REQUIRE_EQ(ast->items[0].route.statements.len, 1u);
    const AstStatement& stmt = *ast->items[0].route.statements[0];
    REQUIRE_EQ(stmt.response_headers.len, 2u);
    CHECK(stmt.response_headers[0].key.eq(lit("X-Service")));
    CHECK(stmt.response_headers[0].value.eq(lit("auth")));
    CHECK(stmt.response_headers[1].key.eq(lit("Cache-Control")));
    CHECK(stmt.response_headers[1].value.eq(lit("no-store")));
    auto hir = analyze_file_heap(ast.value());
    REQUIRE(hir);
    const auto& term = hir->routes[0].control.direct_term;
    REQUIRE_EQ(term.response_headers.len, 2u);
    CHECK(term.response_headers[0].key.eq(lit("X-Service")));
    CHECK(term.response_headers[0].value.eq(lit("auth")));
    CHECK(term.response_headers[1].key.eq(lit("Cache-Control")));
    CHECK(term.response_headers[1].value.eq(lit("no-store")));
    auto mir = build_mir_heap(hir.value());
    REQUIRE(mir);
    FrontendRirModule rir{};
    auto lowered = lower_to_rir(mir.value(), rir);
    REQUIRE(lowered);
    REQUIRE_EQ(rir.module.header_set_count, 1u);
    REQUIRE_EQ(rir.module.header_sets[0].count, 2u);
    REQUIRE_EQ(rir.module.header_sets[0].offset, 0u);
    CHECK(rir.module.header_keys[0].eq(lit("X-Service")));
    CHECK(rir.module.header_values[0].eq(lit("auth")));
    CHECK(rir.module.header_keys[1].eq(lit("Cache-Control")));
    CHECK(rir.module.header_values[1].eq(lit("no-store")));
    rir.destroy();
}

TEST(frontend, parse_return_response_headers_only) {
    // Redirect-style response: headers without a body. Verify
    // response_body_count stays 0 and header_set_count rises to 1.
    const char* src =
        "route GET \"/old\" { return response(301, headers: "
        "{ \"Location\": \"/new\" }) }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(ast);
    auto hir = analyze_file_heap(ast.value());
    REQUIRE(hir);
    auto mir = build_mir_heap(hir.value());
    REQUIRE(mir);
    FrontendRirModule rir{};
    auto lowered = lower_to_rir(mir.value(), rir);
    REQUIRE(lowered);
    CHECK_EQ(rir.module.response_body_count, 0u);
    REQUIRE_EQ(rir.module.header_set_count, 1u);
    REQUIRE_EQ(rir.module.header_sets[0].count, 1u);
    CHECK(rir.module.header_keys[0].eq(lit("Location")));
    CHECK(rir.module.header_values[0].eq(lit("/new")));
    rir.destroy();
}

TEST(frontend, parse_return_response_headers_dedup_across_routes) {
    // Two routes emit the same header set → intern returns the same
    // 1-based idx; header_set_count stays at 1.
    const char* src =
        "route GET \"/a\" { return response(200, headers: { \"X-Cached\": \"1\" }) }\n"
        "route GET \"/b\" { return response(200, headers: { \"X-Cached\": \"1\" }) }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(ast);
    auto hir = analyze_file_heap(ast.value());
    REQUIRE(hir);
    auto mir = build_mir_heap(hir.value());
    REQUIRE(mir);
    FrontendRirModule rir{};
    auto lowered = lower_to_rir(mir.value(), rir);
    REQUIRE(lowered);
    // Only one set interned despite two sources.
    CHECK_EQ(rir.module.header_set_count, 1u);
    CHECK_EQ(rir.module.header_pool_used, 1u);
    rir.destroy();
}

TEST(frontend, parse_return_response_rejects_duplicate_header_key) {
    const char* src =
        "route GET \"/x\" { return response(200, headers: "
        "{ \"X-Foo\": \"1\", \"X-Foo\": \"2\" }) }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(!ast);
    CHECK_EQ(ast.error().code, FrontendError::UnexpectedToken);
    CHECK(ast.error().detail.eq(lit("X-Foo")));
}

TEST(frontend, parse_return_response_rejects_empty_headers_dict) {
    // `headers: {}` is explicitly rejected; omit the kwarg to mean
    // "no custom headers".
    const char* src = "route GET \"/x\" { return response(200, headers: {}) }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(!ast);
    CHECK_EQ(ast.error().code, FrontendError::UnsupportedSyntax);
}

TEST(frontend, parse_return_response_rejects_crlf_in_header_value) {
    // Header values must not contain CR/LF — would let a source author
    // inject a second header (response-splitting) or break the wire
    // framing. `\r` is within the lexer's allowed string bytes, so the
    // parser has to enforce this. The error detail must point at the
    // value bytes (not the key) so the diagnostic highlights the
    // offending string rather than a well-formed key.
    const char* src =
        "route GET \"/x\" { return response(200, headers: "
        "{ \"X-Bad\": \"a\rInjected: 1\" }) }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(!ast);
    CHECK_EQ(ast.error().code, FrontendError::UnsupportedSyntax);
    // Error detail carries the value bytes, proving the span was
    // taken from val_tok, not key_tok.
    CHECK(ast.error().detail.eq(lit("a\rInjected: 1")));
}

TEST(frontend, parse_return_response_rejects_colon_in_header_key) {
    // `:` in a key would be ambiguous once serialized ("Foo:Bar: v"
    // parses as key "Foo" value "Bar: v" at the wire level). Reject
    // at parse time to keep keys unambiguous.
    const char* src =
        "route GET \"/x\" { return response(200, headers: "
        "{ \"X:Bad\": \"1\" }) }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(!ast);
    CHECK_EQ(ast.error().code, FrontendError::UnsupportedSyntax);
}

TEST(frontend, parse_return_response_rejects_empty_header_key) {
    // Empty header name is invalid per HTTP.
    const char* src =
        "route GET \"/x\" { return response(200, headers: "
        "{ \"\": \"1\" }) }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(!ast);
    CHECK_EQ(ast.error().code, FrontendError::UnsupportedSyntax);
}

TEST(frontend, parse_return_response_rejects_space_in_header_key) {
    // Spaces aren't in the HTTP tchar grammar — reject `"X Foo"` so
    // sloppy names don't slip through and later fail to match the
    // case-insensitive Content-Type suppression check.
    const char* src =
        "route GET \"/x\" { return response(200, headers: "
        "{ \"X Foo\": \"1\" }) }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(!ast);
    CHECK_EQ(ast.error().code, FrontendError::UnsupportedSyntax);
}

TEST(frontend, parse_return_response_rejects_case_insensitive_duplicate_key) {
    // HTTP field names are case-insensitive — `"X-Foo"` and `"x-foo"`
    // are the same header and must be rejected as duplicates.
    const char* src =
        "route GET \"/x\" { return response(200, headers: "
        "{ \"X-Foo\": \"1\", \"x-foo\": \"2\" }) }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(!ast);
    CHECK_EQ(ast.error().code, FrontendError::UnexpectedToken);
    CHECK(ast.error().detail.eq(lit("x-foo")));
}

TEST(frontend, parse_return_response_rejects_reserved_header_names) {
    // Content-Length / Transfer-Encoding / Connection are
    // runtime-managed; user attempts to set them would create CL/TE
    // smuggling-style inconsistencies or conflict with the keep-alive
    // decision. Rejected at parse time regardless of case.
    const char* kContentLength =
        "route GET \"/x\" { return response(200, headers: { \"Content-Length\": \"0\" }) }\n";
    const char* kTransferEncoding =
        "route GET \"/x\" { return response(200, headers: "
        "{ \"transfer-encoding\": \"chunked\" }) }\n";
    const char* kConnection =
        "route GET \"/x\" { return response(200, headers: { \"CONNECTION\": \"close\" }) }\n";
    const char* kCases[] = {kContentLength, kTransferEncoding, kConnection};
    for (const char* src : kCases) {
        auto lexed = lex(lit(src));
        REQUIRE(lexed);
        auto ast = parse_file_heap(lexed.value());
        REQUIRE(!ast);
        CHECK_EQ(ast.error().code, FrontendError::UnsupportedSyntax);
    }
}

TEST(frontend, parse_return_response_body_and_headers_order_independent) {
    // Kwargs can appear in either order; both propagate.
    const char* src_a =
        "route GET \"/a\" { return response(200, body: \"hi\", "
        "headers: { \"X-A\": \"1\" }) }\n";
    const char* src_b =
        "route GET \"/a\" { return response(200, headers: { \"X-A\": \"1\" }, "
        "body: \"hi\") }\n";
    for (const char* src : {src_a, src_b}) {
        auto lexed = lex(lit(src));
        REQUIRE(lexed);
        auto ast = parse_file_heap(lexed.value());
        REQUIRE(ast);
        const AstStatement& stmt = *ast->items[0].route.statements[0];
        CHECK(stmt.has_response_body);
        CHECK(stmt.response_body.eq(lit("hi")));
        REQUIRE_EQ(stmt.response_headers.len, 1u);
        CHECK(stmt.response_headers[0].key.eq(lit("X-A")));
    }
}

TEST(frontend, lex_duration_suffix_boundary) {
    // `5ms` is one DurLit; the suffix must sit at a token boundary so
    // `5mystery` stays `5` (IntLit) + `mystery` (Ident). Similarly
    // `5ms2` can't consume `s2` — the boundary check rejects the
    // whole suffix, yielding `5` (IntLit) + `ms2` (Ident).
    struct Case {
        const char* src;
        TokenType first_type;
        const char* first_text;  // nullptr = don't check text
        u32 token_count;         // including the EOF token
    };
    const Case cases[] = {
        {"5ms", TokenType::DurLit, "5ms", 2},
        {"500ms", TokenType::DurLit, "500ms", 2},
        {"2s", TokenType::DurLit, "2s", 2},
        {"5m", TokenType::DurLit, "5m", 2},
        {"1h", TokenType::DurLit, "1h", 2},
        {"5mystery", TokenType::IntLit, "5", 3},
        {"5ms2", TokenType::IntLit, "5", 3},
        {"5sec", TokenType::IntLit, "5", 3},
        {"5", TokenType::IntLit, "5", 2},
    };
    for (const auto& tc : cases) {
        auto lexed = lex(lit(tc.src));
        REQUIRE(lexed);
        REQUIRE_EQ(lexed->tokens.len, tc.token_count);
        CHECK_EQ(static_cast<u8>(lexed->tokens[0].type), static_cast<u8>(tc.first_type));
        if (tc.first_text) CHECK(lexed->tokens[0].text.eq(lit(tc.first_text)));
    }
}

TEST(frontend, parse_route_accepts_wait_statement) {
    const char* src = "route GET \"/sleep\" { wait(1000) wait(downstream.recv()) return 200 }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(ast);
    REQUIRE_EQ(ast->items.len, 1u);
    const auto& route = ast->items[0].route;
    REQUIRE_EQ(route.statements.len, 3u);
    CHECK_EQ(static_cast<u8>(route.statements[0]->kind), static_cast<u8>(AstStmtKind::Wait));
    CHECK_EQ(route.statements[0]->status_code, 1000);  // ms stored in status_code field
    CHECK(!route.statements[0]->has_wait_expr);
    CHECK_EQ(static_cast<u8>(route.statements[1]->kind), static_cast<u8>(AstStmtKind::Wait));
    CHECK(route.statements[1]->has_wait_expr);
    CHECK_EQ(static_cast<u8>(route.statements[2]->kind),
             static_cast<u8>(AstStmtKind::ReturnStatus));
    CHECK_EQ(route.statements[2]->status_code, 200);
}

TEST(frontend, parse_route_accepts_wait_any_statement) {
    const char* src =
        "route GET \"/x\" { wait any { downstream.recv() => { return 204 } timer(250) => { "
        "return 408 } } }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(ast);
    REQUIRE_EQ(ast->items.len, 1u);
    const auto& route = ast->items[0].route;
    REQUIRE_EQ(route.statements.len, 1u);
    CHECK_EQ(static_cast<u8>(route.statements[0]->kind), static_cast<u8>(AstStmtKind::WaitAny));
    REQUIRE_EQ(route.statements[0]->match_arms.len, 2u);
    CHECK_EQ(static_cast<u8>(route.statements[0]->match_arms[0].pattern->kind),
             static_cast<u8>(AstExprKind::MethodCall));
    CHECK_EQ(static_cast<u8>(route.statements[0]->match_arms[1].pattern->kind),
             static_cast<u8>(AstExprKind::Call));
}

TEST(frontend, parse_route_accepts_wait_any_arm_result_binding) {
    const char* src =
        "route GET \"/x\" { wait any { ev = downstream.recv() => { return 204 } "
        "deadline = timer(250) => { return 408 } } }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(ast);
    REQUIRE_EQ(ast->items.len, 1u);
    const AstStatement& wait_any = *ast->items[0].route.statements[0];
    REQUIRE_EQ(wait_any.match_arms.len, 2u);
    CHECK(wait_any.match_arms[0].bind_value);
    CHECK(wait_any.match_arms[0].bind_name.eq(lit("ev")));
    CHECK(wait_any.match_arms[1].bind_value);
    CHECK(wait_any.match_arms[1].bind_name.eq(lit("deadline")));
}

TEST(frontend, analyze_records_wait_in_hir_route) {
    const char* src = "route GET \"/sleep\" { wait(1000) return 200 }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(ast);
    auto hir = analyze_file_heap(ast.value());
    REQUIRE(hir);
    REQUIRE_EQ(hir->routes.len, 1u);
    REQUIRE_EQ(hir->routes[0].waits.len, 1u);
    CHECK_EQ(hir->routes[0].waits[0].ms, 1000);
}

TEST(frontend, analyze_wait_any_statement_lowers_to_any_wait_and_if_control) {
    const char* src =
        "route GET \"/x\" { wait any { downstream.recv() => { return 204 } timer(250) => { "
        "return 408 } } }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(ast);
    auto hir = analyze_file_heap(ast.value());
    REQUIRE(hir);
    REQUIRE_EQ(hir->routes[0].waits.len, 1u);
    CHECK_EQ(hir->routes[0].waits[0].event_kind, WaitEventKind::Any);
    CHECK_EQ(hir->routes[0].waits[0].ms, 250u);
    CHECK_EQ(hir->routes[0].waits[0].arm_mask,
             static_cast<u8>(kWaitEventArmRecv | kWaitEventArmTimer));
    CHECK_EQ(static_cast<u8>(hir->routes[0].control.kind), static_cast<u8>(HirControlKind::If));
    CHECK_EQ(static_cast<u8>(hir->routes[0].control.cond.kind),
             static_cast<u8>(HirExprKind::WaitField));
    REQUIRE(hir->routes[0].control.cond.lhs != nullptr);
    CHECK_EQ(static_cast<u8>(hir->routes[0].control.cond.lhs->kind),
             static_cast<u8>(HirExprKind::WaitResult));
    CHECK_EQ(hir->routes[0].locals.len, 0u);
    CHECK_EQ(hir->routes[0].control.then_term.status_code, 408u);
    CHECK_EQ(hir->routes[0].control.else_term.status_code, 204u);
}

TEST(frontend, wait_any_direct_arm_json_sees_route_struct_locals) {
    const char* src = R"rut(
struct Payload { path: str }
route GET "/x" {
    let payload = Payload(path: req.path)
    wait any {
        downstream.recv() => { return 204 }
        timer(250) => { return 408, json(payload) }
    }
}
)rut";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(ast);
    auto hir = analyze_file_heap(ast.value());
    REQUIRE(hir);
    const auto& route = hir->routes[0];
    REQUIRE_EQ(route.control.kind, HirControlKind::If);
    CHECK(route.control.then_term.has_dynamic_response_body);
    CHECK_EQ(route.control.then_term.json_value_ref_indices.len, 1u);

    auto mir = build_mir_heap(hir.value());
    REQUIRE(mir);
    FrontendRirModule rir{};
    REQUIRE(lower_to_rir(mir.value(), rir));
    rir.destroy();
}

TEST(frontend, analyze_wait_any_arm_result_binding_is_arm_local) {
    const char* src =
        "route GET \"/x\" { wait any { "
        "ev = downstream.recv() => { if ev.ok { return 204 } else { return 400 } } "
        "deadline = timer(250) => { if deadline.timer { return 408 } else { return 500 } } "
        "} }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(ast);
    auto hir = analyze_file_heap(ast.value());
    REQUIRE(hir);
    REQUIRE_EQ(hir->routes[0].waits.len, 1u);
    CHECK_EQ(static_cast<u8>(hir->routes[0].control.kind), static_cast<u8>(HirControlKind::Match));
    CHECK_EQ(static_cast<u8>(hir->routes[0].control.match_expr.kind),
             static_cast<u8>(HirExprKind::WaitField));
    CHECK(hir->routes[0].control.match_expr.str_value.eq(lit("kind")));
    REQUIRE_EQ(hir->routes[0].control.match_arms.len, 2u);
    CHECK_EQ(static_cast<u8>(hir->routes[0].control.match_arms[0].body_kind),
             static_cast<u8>(HirMatchArm::BodyKind::If));
    CHECK_EQ(static_cast<u8>(hir->routes[0].control.match_arms[0].cond.kind),
             static_cast<u8>(HirExprKind::WaitField));
    CHECK(hir->routes[0].control.match_arms[0].cond.str_value.eq(lit("ok")));
    CHECK_EQ(static_cast<u8>(hir->routes[0].control.match_arms[1].body_kind),
             static_cast<u8>(HirMatchArm::BodyKind::If));
    CHECK(hir->routes[0].control.match_arms[1].cond.str_value.eq(lit("timer")));
    CHECK_EQ(hir->routes[0].locals.len, 0u);

    auto mir = build_mir_heap(hir.value());
    REQUIRE(mir);
    FrontendRirModule rir{};
    auto lowered = lower_to_rir(mir.value(), rir);
    REQUIRE(lowered);
    rir.destroy();
}

