    CHECK(ast->items[1].route.statements[0]->expr.field_inits[0].name.eq(lit("token")));
    CHECK(ast->items[1].route.statements[0]->expr.field_inits[1].name.eq(lit("retry")));
    auto hir = analyze_file_heap(ast.value());
