        "      match const true {\n"
        "        true => v\n"
        "        false => 500\n"
        "      }\n"
        "    }\n"
        "    .err => 404\n"
        "  }\n"
        "}\n"
        "route GET \"/users\" { let code = pick(Result.ok(200)) if code == 200 { return 200 } else "
        "{ return 500 } }\n";
