TEST(frontend, guard_else_block_local_named_error_gets_hidden_variant) {
    const char* src =
        "route GET \"/users\" { guard false else { let failed = error(.timeout) if true { return "
        "401 } else { return 500 } } return 200 }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(ast);
    auto hir = analyze_file_heap(ast.value());
    REQUIRE(hir);
    REQUIRE_EQ(hir->variants.len, 1u);
    REQUIRE_EQ(hir->routes[0].guards.len, 1u);
    REQUIRE_EQ(hir->routes[0].guards[0].fail_body.locals.len, 1u);
    const auto& local = hir->routes[0].guards[0].fail_body.locals[0];
    CHECK_EQ(local.error_variant_index, 0u);
    CHECK_EQ(local.init.error_variant_index, 0u);
    CHECK_EQ(local.init.error_case_index, 0u);
}
TEST(frontend, guard_let_binds_success_value) {
    const char* src =
        "route GET \"/users\" { guard let code = 200 else { return 401 } if code == 200 { return "
        "200 } else { return 404 } }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(ast);
    REQUIRE_EQ(ast->items[0].route.statements.len, 2u);
    CHECK_EQ(static_cast<u8>(ast->items[0].route.statements[0]->kind),
             static_cast<u8>(AstStmtKind::Guard));
    CHECK(ast->items[0].route.statements[0]->bind_value);
    auto hir = analyze_file_heap(ast.value());
    REQUIRE(hir);
    REQUIRE_EQ(hir->routes[0].locals.len, 1u);
    CHECK(hir->routes[0].locals[0].name.eq(lit("code")));
    CHECK_EQ(static_cast<u8>(hir->routes[0].locals[0].type), static_cast<u8>(HirTypeKind::I32));
    CHECK_FALSE(hir->routes[0].locals[0].may_error);
    CHECK_EQ(static_cast<u8>(hir->routes[0].control.kind), static_cast<u8>(HirControlKind::If));
    auto mir = build_mir_heap(hir.value());
    REQUIRE(mir);
    REQUIRE_EQ(mir->functions[0].locals.len, 1u);
    REQUIRE_EQ(mir->functions[0].blocks.len, 5u);
    CHECK_EQ(static_cast<u8>(mir->functions[0].blocks[0].term.kind),
             static_cast<u8>(MirTerminatorKind::Branch));
    CHECK_EQ(static_cast<u8>(mir->functions[0].blocks[1].term.kind),
             static_cast<u8>(MirTerminatorKind::Branch));
}
TEST(frontend, guard_let_takes_else_branch_on_known_nil) {
    // Spec §3.3.7: guard let treats nil and error alike — no usable value means
    // the else branch. A known-nil init folds the condition to false, and (like a
    // known-error init) the unreachable success-path binding is SKIPPED:
    // previously materializing it left an always-else route that lower_to_rir
    // rejected (PR #162 re-review — known-nil == known-error here).
    const char* src =
        "route GET \"/users\" { guard let maybe = nil else { return 401 } return 200 }\n";
    auto lexed = lex(lit(src));
    REQUIRE(lexed);
    auto ast = parse_file_heap(lexed.value());
    REQUIRE(ast);
    auto hir = analyze_file_heap(ast.value());
    REQUIRE(hir);
    // Success-path binding skipped (unreachable) — no `maybe` local.
    REQUIRE_EQ(hir->routes[0].locals.len, 0u);
    CHECK_EQ(static_cast<u8>(hir->routes[0].guards[0].cond.kind),
             static_cast<u8>(HirExprKind::BoolLit));
    CHECK_FALSE(hir->routes[0].guards[0].cond.bool_value);
    // The whole route now lowers end-to-end (previously rejected at lower_to_rir).
    FrontendRirModule rir{};
    CHECK(lower_src_to_rir(src, rir));
    rir.destroy();
}
