    const auto& arms = hir->routes[0].for_loops[0].body.matches[0].arms;
    REQUIRE_EQ(arms[0].locals.len, 1u);
    CHECK(arms[0].locals[0].name.eq(lit("path")));
    CHECK(arms[0].has_arm_guard);
