    REQUIRE_EQ(term.json_segments.len, 2u);
    CHECK(term.json_segments[0].eq(lit("{\"path\":")));
    CHECK(term.json_segments[1].eq(lit("}")));

    auto mir = build_mir_heap(hir.value());
    REQUIRE(mir);
